"""Generated by scripts/export_agent.py. Regenerate after changing features/history."""

import os

import numpy as np
import onnxruntime as ort

LIDAR_RAYS = 100
LIDAR_MAX = 15.0  # m
SPEED_MAX = 10.0  # m/s
STEER_MAX = 0.4189  # rad
REQUIRED_LAPS = 3
MAX_OPPONENTS = 3
STATUS_ACTIVE = 1

EGO_SIZE = LIDAR_RAYS + 5
# mask, x_rel, y_rel, sin yaw_rel, cos yaw_rel, speed, race gap
OPPONENT_SIZE = 7
FEATURE_SIZE = EGO_SIZE + MAX_OPPONENTS * OPPONENT_SIZE


def _number(mapping, key: str, default: float = 0.0) -> float:
    try:
        value = float(mapping.get(key, default))
    except (AttributeError, TypeError, ValueError, OverflowError):
        return default
    return value if np.isfinite(value) else default


def _lidar(obs: dict) -> np.ndarray:
    """100 ranges in metres. Missing rays read as free space, the reading of an empty scan."""
    try:
        rays = np.asarray(obs.get("lidar", ()), dtype=np.float64).ravel()
    except (TypeError, ValueError):
        rays = np.empty(0)
    out = np.full(LIDAR_RAYS, LIDAR_MAX)
    out[: min(rays.size, LIDAR_RAYS)] = rays[:LIDAR_RAYS]
    return np.nan_to_num(out, nan=LIDAR_MAX, posinf=LIDAR_MAX, neginf=0.0)


def adapt_observation(obs: dict) -> dict:
    """Raw `get_obs` dict -> canonical form with explicit units and a fixed opponent table.

    `opponents` is a (MAX_OPPONENTS, 6) array (x_rel, y_rel, yaw_rel, speed, progress,
    lap_count) of the active opponents, nearest first, zero-padded; `mask` marks the filled
    rows. The ego slot and inactive cars (status != 1) are left out, whatever their values.
    """
    raw = obs.get("opponents")
    slots = raw.values() if isinstance(raw, dict) else ()
    active = []
    for slot in slots:
        if not isinstance(slot, dict) or _number(slot, "status") != STATUS_ACTIVE:
            continue
        keys = ("x_rel", "y_rel", "yaw_rel", "speed", "progress", "lap_count")
        active.append([_number(slot, k) for k in keys])
    # nearest first, ties broken on the values themselves: the slot order never matters
    active.sort(key=lambda row: (float(np.hypot(row[0], row[1])), row))
    active = active[:MAX_OPPONENTS]

    opponents = np.zeros((MAX_OPPONENTS, 6))
    mask = np.zeros(MAX_OPPONENTS, dtype=bool)
    if active:
        opponents[: len(active)] = active
        mask[: len(active)] = True
    return {
        "lidar": _lidar(obs),
        "velocity": _number(obs, "velocity"),
        "steering": _number(obs, "steering"),
        "progress": _number(obs, "progress"),
        "lap_count": _number(obs, "lap_count"),
        "opponents": opponents,
        "mask": mask,
    }


def build_features(obs: dict) -> np.ndarray:
    """Raw `get_obs` dict of one car -> float32 vector of FEATURE_SIZE values in [-1, 1]."""
    c = adapt_observation(obs)
    phase = 2.0 * np.pi * c["progress"]
    ego_laps = c["lap_count"] + c["progress"]
    ego = [
        c["velocity"] / SPEED_MAX,
        c["steering"] / STEER_MAX,
        np.sin(phase),
        np.cos(phase),
        c["lap_count"] / REQUIRED_LAPS,
    ]
    rows = np.zeros((MAX_OPPONENTS, OPPONENT_SIZE))
    for i in np.flatnonzero(c["mask"]):
        x, y, yaw, speed, progress, laps = c["opponents"][i]
        rows[i] = [
            1.0,
            x / LIDAR_MAX,
            y / LIDAR_MAX,
            np.sin(yaw),
            np.cos(yaw),
            speed / SPEED_MAX,
            # laps ahead (+) or behind (-), from each car's own start: a few metres off on
            # a staggered grid, enough to tell ahead from lapped. Jumps by a whole lap when
            # a car reverses behind its line (progress wraps, lap_count never drops): see
            # docs/features.md
            laps + progress - ego_laps,
        ]
    vec = np.concatenate([c["lidar"] / LIDAR_MAX, ego, rows.ravel()])
    return np.clip(vec, -1.0, 1.0).astype(np.float32)


DEPTH = 4
DECISION_FREQ_HZ = 20
# Key of the cars whose obs has no usable agent_id: kept apart from a real car 0.
MISSING_ID = -1
# agent_loader.create_dummy_obs, sent once to predict() before the race: every ray at 5 m.
PROBE_LIDAR = 5.0


def _get(mapping, key: str):
    try:
        return mapping.get(key)
    except AttributeError:
        return None


def _scalar(value) -> float | None:
    """A finite float, or None for anything else: bools, arrays, text, overflow, NaN."""
    if isinstance(value, bool):
        return None
    try:
        number = np.asarray(value, dtype=np.float64)
    except (TypeError, ValueError, OverflowError):
        return None
    if number.ndim != 0 or not np.isfinite(number):
        return None
    return float(number)


def _integer(value) -> int | None:
    number = _scalar(value)
    return int(number) if number is not None and number == int(number) else None


def car_id(obs: dict) -> int:
    """`obs["agent_id"]`, or MISSING_ID when it is absent or not a non-negative integer."""
    value = _integer(_get(obs, "agent_id"))
    return value if value is not None and value >= 0 else MISSING_ID


def decision_step(info: dict) -> int | None:
    """Step counter of `get_step_info`: `step_count`, else `time_elapsed` x 20 Hz, else None."""
    step = _integer(_get(info, "step_count"))
    if step is not None:
        return step
    elapsed = _scalar(_get(info, "time_elapsed"))
    if elapsed is None or not np.isfinite(elapsed * DECISION_FREQ_HZ):
        return None
    return round(elapsed * DECISION_FREQ_HZ)


def is_probe(obs: dict, info: dict) -> bool:
    """True for the loader's dry-run call, whose dummy frame must not enter any history."""
    if decision_step(info) not in (0, None) or _scalar(_get(obs, "velocity")) != 0.0:
        return False
    try:
        rays = np.asarray(_get(obs, "lidar"), dtype=np.float64)
    except (TypeError, ValueError):
        return False
    return rays.size > 0 and bool(np.all(rays == PROBE_LIDAR))


class CarHistory:
    """The last DEPTH feature vectors of each car, oldest first."""

    def __init__(self, depth: int = DEPTH):
        if depth < 1:
            raise ValueError(f"depth must be >= 1, got {depth}")
        self.depth = depth
        self._frames: dict[int, np.ndarray] = {}
        self._last_step: dict[int, int | None] = {}
        self._last_laps: dict[int, int] = {}

    def reset(self) -> None:
        self._frames.clear()
        self._last_step.clear()
        self._last_laps.clear()

    def push(self, obs: dict, info: dict, features: np.ndarray) -> np.ndarray:
        """Add this decision's features to the car of `obs`; return its float32 stack.

        The result has `depth * features.size` values: the oldest frame first, `features`
        last. A dry-run probe gets a stack of its own frame and leaves the memory untouched.
        """
        frame = np.asarray(features, dtype=np.float32).ravel()
        if is_probe(obs, info):
            return np.tile(frame, self.depth)

        car = car_id(obs)
        step = decision_step(info)
        laps = _integer(_get(obs, "lap_count"))
        frames = self._frames.get(car)
        if frames is None or frames.shape[1] != frame.size or self._new_episode(car, step, laps):
            frames = np.tile(frame, (self.depth, 1))
        else:
            frames = np.concatenate([frames[1:], frame[None]])

        self._frames[car] = frames
        self._last_step[car] = step
        if laps is not None:
            self._last_laps[car] = laps
        return frames.ravel().copy()

    def _new_episode(self, car: int, step: int | None, laps: int | None) -> bool:
        last = self._last_step.get(car)
        # Each car decides once per step: anything but the next step is another episode,
        # or a gap after which the memory no longer describes the present. A harness that
        # calls a car every other step restarts it each time (docs/history.md, limits).
        if step is not None and last is not None and step != last + 1:
            return True
        last_laps = self._last_laps.get(car)
        return laps is not None and last_laps is not None and laps < last_laps


class Agent:
    def __init__(self):
        options = ort.SessionOptions()
        options.intra_op_num_threads = 1
        options.inter_op_num_threads = 1
        path = os.path.join(os.path.dirname(__file__), "model.onnx")
        self.session = ort.InferenceSession(path, options, providers=["CPUExecutionProvider"])
        self.input_name = self.session.get_inputs()[0].name
        self.history = CarHistory(1)

    def predict(self, obs, info):
        vector = self.history.push(obs, info, build_features(obs))
        action = self.session.run(None, {self.input_name: vector[None]})[0][0]
        action = np.clip(np.nan_to_num(action, nan=0.0, posinf=1.0, neginf=-1.0), -1.0, 1.0)
        friction = min(max(_number(info, "friction_current", 1.0), 0.05), 1.0)
        speed = min(float(4.0 + 6.0 * action[0]), 4.75 * friction**0.5)
        return speed, float(0.4189 * action[1])
